WITH with_last AS (SELECT s.*, latest.stock_qty FROM suppliers s LEFT JOIN LATERAL (SELECT c.stock_qty FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, supplier_name, country, rating, CASE WHEN country RLIKE '^(UK|SG)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS country_zone FROM with_last ORDER BY id DESC NULLS FIRST LIMIT 5;
